import{_ as t,o,c as d,ag as a}from"./chunks/framework.B61-P76f.js";const p=JSON.parse('{"title":"Dev & production bundles","description":"","frontmatter":{},"headers":[],"relativePath":"guide/bundles.md","filePath":"guide/bundles.md"}'),r={name:"guide/bundles.md"};function n(i,e,c,s,l,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="dev-production-bundles" tabindex="-1">Dev &amp; production bundles <a class="header-anchor" href="#dev-production-bundles" aria-label="Permalink to &quot;Dev &amp; production bundles&quot;">​</a></h1><p>The package ships two bundle flavors from one source, selected automatically through the <code>development</code> / <code>production</code> <a href="https://nodejs.org/api/packages.html#community-conditions-definitions" target="_blank" rel="noreferrer">export conditions</a>.</p><h2 id="what-each-flavor-does" tabindex="-1">What each flavor does <a class="header-anchor" href="#what-each-flavor-does" aria-label="Permalink to &quot;What each flavor does&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>development</th><th>production (default)</th></tr></thead><tbody><tr><td>Operation creators validate ranges/enums</td><td>✅ throw <code>TypeError</code> / <code>RangeError</code></td><td>❌ stripped</td></tr><tr><td>Builder misuse guards (ops on a group root)</td><td>✅ throw</td><td>silently no-op</td></tr><tr><td><code>videoPath</code> / <code>nthUrl</code> input checks</td><td>✅ throw</td><td>❌ stripped</td></tr><tr><td>Structural errors (<code>parseCdnUrl</code>, <code>parseGroupId</code>)</td><td>✅ throw</td><td>✅ throw</td></tr><tr><td><code>validate</code> module</td><td>✅ fully functional</td><td>✅ fully functional</td></tr><tr><td>Minified</td><td>no</td><td>yes</td></tr></tbody></table><p>The contract is to catch mistakes in development; production is garbage in, garbage out. <code>quality(&#39;ultra&#39;)</code> throws on your machine and in CI; in a production build it serializes to <code>-/quality/ultra/</code> and the CDN responds with an error instead.</p><p>Structural errors stay in both flavors because callers rely on them for control flow. A <code>try/catch</code> around <code>parseCdnUrl</code> behaves identically everywhere.</p><h2 id="what-each-function-does-when-it-fails" tabindex="-1">What each function does when it fails <a class="header-anchor" href="#what-each-function-does-when-it-fails" aria-label="Permalink to &quot;What each function does when it fails&quot;">​</a></h2><p>Four failure modes exist, and which one you get is a property of the function, not of the bundle. This is the whole map:</p><table tabindex="0"><thead><tr><th>Failure mode</th><th>Functions</th><th>In production</th></tr></thead><tbody><tr><td><strong>Always throws</strong> — structural, you cannot proceed</td><td><code>parseCdnUrl</code> and the per-kind parsers, <code>parseGroupId</code>, <code>serializeCdnUrl</code>&#39;s addressing guard, <code>cdn.base(&#39;&#39;)</code>, <code>cdn.file</code>/<code>group</code>/<code>gif2video</code> before a base is bound</td><td>throws</td></tr><tr><td><strong>Dev-only throw, then no-op</strong> — misuse the facade catches for you</td><td>builder and chain guards: operations on a group root, a filename on a proxy</td><td>returns the receiver unchanged</td></tr><tr><td><strong>Dev-only throw, then garbage in / garbage out</strong> — value checks</td><td>every operation creator (<code>quality(&#39;ultra&#39;)</code>, out-of-range sizes, bad enums), <code>videoPath</code>/<code>nthUrl</code> input checks</td><td>serializes the bad value as given</td></tr><tr><td><strong>Never throws, returns findings</strong></td><td><code>validateOperations</code> and the rest of the <code>validate</code> entry</td><td>identical to development</td></tr></tbody></table><p>Two functions sit outside the table because their behaviour depends on the runtime rather than the bundle: <a href="/uploadcare-js-api-clients/cdn-url/guide/cdn-base.html#sync-or-async"><code>prefixedCdnBaseAsync</code></a> needs WebCrypto, so it fails on a plain <code>http://</code> origin, where browsers hide <code>crypto.subtle</code>; under Node it uses <code>node:crypto</code>. <code>prefixedCdnBase</code> works everywhere.</p><p>The string level (<a href="/uploadcare-js-api-clients/cdn-url/guide/string-level-api.html"><code>tinyParse</code>/<code>tinyBuild</code></a>) throws nowhere, in either flavor, by design — it does no validation at all.</p><h2 id="who-picks-which-bundle" tabindex="-1">Who picks which bundle <a class="header-anchor" href="#who-picks-which-bundle" aria-label="Permalink to &quot;Who picks which bundle&quot;">​</a></h2><ul><li>Vite, webpack and friends resolve the <code>development</code> condition in dev servers and <code>production</code> in production builds, with no configuration needed.</li><li>Node uses the production bundle by default; opt into the checks with <code>node --conditions=development</code>.</li><li>Unknown or legacy resolvers fall back to production, the safe minimal default.</li></ul><h2 id="validating-at-runtime-anyway" tabindex="-1">Validating at runtime anyway <a class="header-anchor" href="#validating-at-runtime-anyway" aria-label="Permalink to &quot;Validating at runtime anyway&quot;">​</a></h2><p>Stripped checks protect <em>your</em> code from <em>your</em> mistakes. If operation chains come from users or stored data, validate them explicitly. <a href="/uploadcare-js-api-clients/cdn-url/how-to/validate-user-input.html"><code>validateOperations</code></a> works identically in both flavors and returns diagnostics instead of throwing.</p>',15)])])}const f=t(r,[["render",n]]);export{p as __pageData,f as default};
